'use strict';
const KEY='lastro-v3',E=Ledger,FIAT=['BRL','USD'],ASSETS=['BTC','ETH','SOL','USDC','USDT','BNB','BRL','USD'];
const catalog={BTC:{name:'Bitcoin',icon:'₿',css:''},ETH:{name:'Ethereum',icon:'Ξ',css:'eth'},SOL:{name:'Solana',icon:'◎',css:'sol'},USDC:{name:'USD Coin',icon:'$',css:'eth'},USDT:{name:'Tether',icon:'₮',css:'sol'},BNB:{name:'BNB',icon:'◈',css:''},BRL:{name:'Real',icon:'R$',css:'sol'},USD:{name:'Dólar',icon:'$',css:'eth'}};
const markets={mixed:{name:'Contexto misto',level:'amber',usd:{BTC:79200,ETH:3000,SOL:148,BNB:600,USDC:1,USDT:1,USD:1},fx:5.2,rates:'+12 pb',oil:'+3,1%',sp:'−1,4%',copy:'Juros e petróleo sobem; ações recuam. Confira as premissas.'},stress:{name:'Estresse macro',level:'red',usd:{BTC:78500,ETH:2880,SOL:143,BNB:570,USDC:1,USDT:1,USD:1},fx:5.25,rates:'+30 pb',oil:'+8,6%',sp:'−4,0%',copy:'A pressão macro pode exigir revisão mesmo com lucro.'},support:{name:'Recuperação',level:'green',usd:{BTC:82000,ETH:3200,SOL:162,BNB:630,USDC:1,USDT:1,USD:1},fx:5.1,rates:'−8 pb',oil:'−1,8%',sp:'+1,7%',copy:'Contexto melhora; os limites da estratégia continuam válidos.'},break:{name:'Suporte perdido',level:'red',usd:{BTC:73200,ETH:2440,SOL:121,BNB:510,USDC:1,USDT:1,USD:1},fx:5.35,rates:'+30 pb',oil:'+8,6%',sp:'−4,0%',copy:'Preços do exemplo ultrapassam níveis de invalidação.'},target:{name:'Objetivo alcançado',level:'green',usd:{BTC:85600,ETH:3450,SOL:178,BNB:660,USDC:1,USDT:1,USD:1},fx:5.05,rates:'−8 pb',oil:'−1,8%',sp:'+1,7%',copy:'Objetivos do exemplo alcançados; nenhuma parcial é executada automaticamente.'}};
const types={OPENING:'Saldo inicial',BUY:'Compra',SELL:'Venda',CONVERT:'Conversão',DEPOSIT:'Aporte',WITHDRAW:'Retirada',TRANSFER:'Transferência',TAX:'Imposto pago'};
const cl=x=>JSON.parse(JSON.stringify(x));
function demoEvent(id,type,date,asset,qty,other={}){return{id:'demo'+id,sequence:id,date,owner:'Jaime (demo)',venue:'Binance',country:'UNKNOWN',type,asset,qty,price:0,quote:'BRL',fx:1,feeQty:0,feeCurrency:'BRL',feeFx:1,notes:'Exemplo fictício',reference:'DEMO-'+id,...other}}
const seed={version:3,owners:['Jaime (demo)','Eliane (demo)'],scenario:'mixed',events:[
 demoEvent(1,'OPENING','2026-01-01T09:00','USDC',10000,{costBRL:50000}),
 demoEvent(2,'DEPOSIT','2026-01-02T09:00','BRL',5000),
 demoEvent(3,'BUY','2026-08-10T10:00','BTC',.05,{price:76000,quote:'USDC',fx:5,feeQty:3.8,feeCurrency:'USDC',feeFx:5}),
 demoEvent(4,'BUY','2026-08-15T10:00','ETH',1,{price:2800,quote:'USDC',fx:5,feeQty:2.8,feeCurrency:'USDC',feeFx:5}),
 demoEvent(5,'BUY','2026-09-01T10:00','SOL',10,{price:140,quote:'USDC',fx:5.05,feeQty:1.4,feeCurrency:'USDC',feeFx:5.05}),
 demoEvent(6,'SELL','2026-09-15T10:00','BTC',.02,{price:85000,quote:'USDC',fx:5.1,feeQty:1.7,feeCurrency:'USDC',feeFx:5.1}),
 demoEvent(7,'SELL','2026-10-10T10:00','ETH',.25,{price:2500,quote:'USDC',fx:5.2,feeQty:.625,feeCurrency:'USDC',feeFx:5.2}),
 demoEvent(8,'TRANSFER','2026-10-15T10:00','BTC',.01,{toVenue:'Carteira própria',feeQty:.00001,feeCurrency:'BTC',feeFx:400000}),
 demoEvent(9,'TAX','2026-10-20T10:00','BRL',120,{taxSource:'external',taxPeriod:'2026-09',reference:'DEMO-RECIBO',notes:'Valor informado para demonstrar o registro; não calculado pelo app.'}),
 demoEvent(10,'OPENING','2026-01-01T09:00','USDC',4000,{owner:'Eliane (demo)',costBRL:20000}),
 demoEvent(11,'BUY','2026-09-10T10:00','BTC',.02,{owner:'Eliane (demo)',price:75000,quote:'USDC',fx:5.1,feeQty:1.5,feeCurrency:'USDC',feeFx:5.1})
],plans:{'Jaime (demo)|BTC':{stop:74000,target:85000,partial:25,maxRisk:2,reason:'Preservar capital; revisar se perder o suporte e realizar parcial no objetivo.'},'Jaime (demo)|ETH':{stop:2500,target:3400,partial:25,maxRisk:2,reason:'Acompanhar a recuperação com risco limitado.'},'Jaime (demo)|SOL':{stop:125,target:175,partial:25,maxRisk:2,reason:'Exposição pequena com invalidação definida.'},'Eliane (demo)|BTC':{stop:74000,target:85000,partial:25,maxRisk:2,reason:'Entrada em suporte com objetivo e limite de risco definidos.'}},reviews:[]};
let state=cl(seed),recovery=false;function check(s){if(!s||s.version!==3||!Array.isArray(s.events)||!Array.isArray(s.owners)||!s.owners.length||s.owners.some(o=>typeof o!=='string'||!o.trim()||o.includes('|'))||!s.plans||typeof s.plans!=='object'||!Array.isArray(s.reviews)||!Object.hasOwn(markets,s.scenario))throw Error('Backup incompatível com a v3.');if(s.events.some(e=>!s.owners.includes(e.owner)))throw Error('Titular de operação ausente do cadastro.');for(const [key,p] of Object.entries(s.plans)){if(!p||!['stop','target','partial','maxRisk'].every(k=>Number.isFinite(p[k]))||p.stop<=0||p.target<=p.stop||p.partial<=0||p.partial>100||p.maxRisk<=0||p.maxRisk>100||typeof p.reason!=='string')throw Error('Estratégia inválida no backup.');}if(s.reviews.some(x=>!x||typeof x.key!=='string'||typeof x.decision!=='string'||!Number.isFinite(x.price)))throw Error('Revisão inválida no backup.');E.replay(s.events);return s}try{const r=localStorage.getItem(KEY);if(r)state=check(JSON.parse(r))}catch{recovery=true}
let chartDemo=null,chartView='columns';
let page='overview',owner='all',start='2026-01-01',end='2026-10-31',selected='',query='',typeFilter='all';
const $=id=>document.getElementById(id),app=$('app'),modal=$('modal'),form=$('form');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=2)=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}),brl=v=>'R$ '+n(v),qty=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:8}),percent=v=>n(v)+'%',signed=v=>(v>0?'+':'')+brl(v),pk=h=>h.owner+'|'+h.asset;
const mkt=()=>markets[state.scenario];function marks(){let v={BRL:1};for(let[a,p]of Object.entries(mkt().usd))v[a]=p*mkt().fx;return v}
function report(o=owner){return E.replay(state.events,{owner:o,end})}function positions(r=report()){return E.value(r,end<'2026-10-31'?r.marks:marks())}function total(r=report()){return positions(r).reduce((s,h)=>s+h.value,0)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Armazenamento indisponível: exporte o backup antes de fechar.')}}let timer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',4000)}
function pill(t,c='green'){return `<span class="pill ${c==='green'?'':c}"><i class="signal-dot"></i>${esc(t)}</span>`}function button(t,a,primary=false,more=''){return `<button class="btn ${primary?'primary':''}" data-action="${a}" ${more}>${t}</button>`}function textbtn(t,a,more=''){return `<button class="textbtn" data-action="${a}" ${more}>${t}</button>`}
function info(label,text){return `<button type="button" class="info-button" aria-label="Informações: ${esc(label)}" data-help="${esc(text)}"><span aria-hidden="true">i</span></button>`}
function installHelp(){
 const pop=document.createElement('div');pop.id='lastro-help';pop.className='info-popover';pop.setAttribute('popover','manual');pop.setAttribute('role','tooltip');document.body.append(pop);
 let active=null,closeTimer;
 const hide=()=>{clearTimeout(closeTimer);if(active){active.removeAttribute('aria-describedby');active=null;}if(pop.matches(':popover-open'))pop.hidePopover();};
 const open=b=>{clearTimeout(closeTimer);const host=modal.open?modal:document.body;if(pop.parentElement!==host){if(pop.matches(':popover-open'))pop.hidePopover();host.append(pop);}if(active&&active!==b)active.removeAttribute('aria-describedby');active=b;pop.textContent=b.dataset.help.replaceAll('{DATA}',end.split('-').reverse().join('/'));b.setAttribute('aria-describedby',pop.id);if(!pop.matches(':popover-open'))pop.showPopover();const rect=b.getBoundingClientRect(),width=Math.min(330,window.innerWidth-24);pop.style.width=width+'px';pop.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';const h=pop.getBoundingClientRect().height;pop.style.top=(rect.bottom+h+12<window.innerHeight?rect.bottom+8:Math.max(12,rect.top-h-8))+'px';};
 document.addEventListener('pointerover',e=>{const b=e.target.closest('.info-button');if(b)open(b);});
 document.addEventListener('pointerout',e=>{if(e.target.closest('.info-button')&&active!==document.activeElement)closeTimer=setTimeout(hide,180);});
 pop.addEventListener('pointerenter',()=>clearTimeout(closeTimer));pop.addEventListener('pointerleave',hide);
 document.addEventListener('focusin',e=>{const b=e.target.closest('.info-button');if(b)open(b);else hide();});
 document.addEventListener('click',e=>{const b=e.target.closest('.info-button');if(b){e.preventDefault();e.stopImmediatePropagation();open(b);}else if(!pop.contains(e.target))hide();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();e.stopImmediatePropagation();hide();}},true);
 window.addEventListener('scroll',hide,true);window.addEventListener('resize',hide);modal.addEventListener('close',hide);
 const attach=(target,text)=>{const existing=target.querySelector(':scope > .info-button');if(existing)existing.dataset.help+=' '+text;else target.insertAdjacentHTML('beforeend',' '+info(target.textContent,text));};
 const tidy=root=>{
  root.querySelectorAll('.metric').forEach(card=>{const note=card.querySelector('small'),label=card.querySelector('.eyebrow');if(note&&label){label.insertAdjacentHTML('beforeend',info(label.textContent,note.textContent));note.remove();}});
  root.querySelectorAll('p.sub,.head .sub,.chart-caption,.source-note,.filter-note,p.hint').forEach(note=>{
   if(!note.textContent.trim()||note.querySelector('button,input')||note.closest('.operation-line,.timeline2'))return;
   const text=note.textContent.trim();if(note.matches('.head .sub')&&page==='detail')return;if(text.length<65&&!note.matches('.sub,.source-note,.chart-caption,.filter-note'))return;
   let target=note.previousElementSibling;
   if(note.matches('.chart-caption,.source-note'))target=note.parentElement.querySelector('h2');
   if(note.matches('.filter-note')){note.innerHTML='Período '+info('Como os filtros funcionam',text);note.className='filter-help';return;}
   if(target&&target.matches('h1,h2,h3,b,strong,.eyebrow')){attach(target,text);note.remove();}
   else{note.outerHTML='<div class="help-inline">'+info('Como funciona',text)+'</div>';}
  });
  root.querySelectorAll('.comparison>.hint').forEach(note=>{const label=note.parentElement.querySelector('b');if(label){label.insertAdjacentHTML('beforeend',' '+info(label.textContent,note.textContent));note.remove();}});
 };
 const roots=[app,$('filters'),$('fields')];let queued=false;
 const clean=()=>{queued=false;roots.forEach(tidy);};
 const observer=new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(clean);}});roots.forEach(root=>observer.observe(root,{childList:true,subtree:true}));clean();
}

function head(t,s,a=''){return `<div class="head"><div><h1>${t}</h1><p class="sub">${s}</p></div><div class="actionsbar">${a}</div></div>`}function moneyClass(v){return v< -E.EPS?'negative':v>E.EPS?'up':''}
function coin(h){const c=catalog[h.asset]||{name:h.asset,icon:h.asset.slice(0,1),css:'sol'};return `<div class="asset"><span class="coin ${c.css}">${esc(c.icon)}</span><div><b>${esc(h.asset)}</b><small>${esc(h.owner)}</small></div></div>`}
function go(p){page=p;render();window.scrollTo(0,0)}function openHolding(key){selected=key;go('detail')}
function health(h){if(end<'2026-10-31')return{label:'Sem leitura histórica',level:'neutral'};const p=state.plans[pk(h)];if(!p)return{label:FIAT.includes(h.asset)||['USDC','USDT'].includes(h.asset)?'Reserva / caixa':'Sem plano',level:'neutral'};const ref=mkt().usd[h.asset],risk=Math.max(h.average-p.stop*mkt().fx,0)*h.qty/(total(report(h.owner))||1)*100;if(ref<=p.stop)return{label:'Invalidação atingida',level:'red'};if(risk>p.maxRisk)return{label:'Risco acima do limite',level:'red'};if(ref>=p.target)return{label:'Objetivo alcançado',level:'green'};return{label:'Dentro dos níveis',level:'green'}}
function metrics(r){let s=E.period(r,start,end),v=positions(r),un=v.reduce((x,h)=>x+h.unrealized,0);return `<div class="metrics six">${[['Valor da carteira',brl(total(r)),'Soma dos ativos e do caixa em reais em {DATA}. Inclui os saldos até essa data, mesmo anteriores ao início do período. Os preços deste protótipo são simulados; em datas passadas, usa a última referência registrada.',null],['Lucro/prejuízo realizado',signed(s.realized),'Lucro ou prejuízo das operações no período selecionado, incluindo vendas, conversões, variação cambial e custos de transferência. As taxas já estão incluídas. Não desconta os impostos registrados e não é o imposto a pagar.',moneyClass(s.realized)],['Lucro/prejuízo em carteira',signed(un),'Diferença entre o valor dos ativos que você ainda possui e o custo de aquisição desses saldos. Usa as referências de preço em {DATA}; esse resultado ainda pode mudar antes da venda.',moneyClass(un)],['Negociações',String(s.count),`Quantidade de compras, vendas e conversões no período. Das ${s.sales} vendas: ${s.wins} com lucro, ${s.losses} com prejuízo e ${s.flat} sem lucro ou prejuízo. Aportes, retiradas e transferências não entram nessa contagem.`,null],['Taxas das operações',brl(s.fees),'Total de taxas registradas no período, convertido em reais. Inclui taxas de negociação e de rede. Elas já integram os custos ou resultados: não desconte este valor novamente.',null],['Pagamentos de imposto',brl(s.tax),'Soma dos pagamentos de imposto que você cadastrou no período, pela data do pagamento. Por exemplo: um DARF já pago e registrado por você. Não é uma cobrança nem um cálculo do imposto devido. Pode se referir a operações de outro mês.',null]].map(([label,value,hint,c])=>`<div class="card metric"><span class="eyebrow">${label}</span><strong class="${c||''}">${value}</strong><small>${hint}</small></div>`).join('')}</div>`}
function holdingsTable(r){const hs=positions(r);return `<div class="card bottom"><div class="row wrap"><div><h2>Ativos da carteira</h2><p class="sub">Custos históricos em BRL, sem misturar titulares.</p></div>${textbtn('Exportar carteira','exportHoldings')}</div><div class="tablewrap"><table class="holdings-table"><thead><tr><th>Ativo / titular</th><th>Quantidade</th><th>Preço médio / custo ${info('Preço médio / custo','Preço médio por unidade em reais e custo total do saldo em carteira. Calculados pelos custos históricos e taxas, separadamente por titular.')}</th><th>Valor / cotação ${info('Valor / cotação','Valor total da posição e preço de referência por unidade na data Até. Neste protótipo, as cotações de mercado são simuladas.')}</th><th>Lucro/prejuízo ${info('Lucro/prejuízo','Valor da posição menos seu custo de aquisição. O percentual é calculado sobre esse custo. Ainda não foi realizado por venda.')}</th><th>Estratégia / mercado ${info('Estratégia / mercado','Compara o preço com os limites da estratégia e mostra o cenário de mercado simulado. Não prevê preços nem executa ordens.')}</th></tr></thead><tbody>${hs.map(h=>{let healthState=health(h),isRisk=Boolean(state.plans[pk(h)]);return `<tr class="click" data-holding="${esc(pk(h))}" tabindex="0" role="button" aria-label="Detalhar ${esc(h.asset)} de ${esc(h.owner)}"><td>${coin(h)}</td><td>${qty(h.qty)}</td><td><b>${brl(h.average)}</b><br><small class="hint">Custo: ${brl(h.cost)}</small></td><td><b>${brl(h.value)}</b><br><small class="hint">Preço: ${brl(h.mark)}</small></td><td class="${moneyClass(h.unrealized)}"><b>${signed(h.unrealized)}</b><br><small>${h.cost?percent(h.unrealized/h.cost*100):'Custo zero informado'}</small></td><td>${pill(healthState.label,healthState.level)}${isRisk?`<div style="margin-top:6px">${pill(end<'2026-10-31'?'Contexto atual simulado':mkt().name,end<'2026-10-31'?'neutral':mkt().level)}</div>`:''}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Sem saldo. Registre um aporte, compra ou saldo inicial.</td></tr>'}</tbody></table></div><p class="source-note">${end<'2026-10-31'?'Preços históricos: última referência registrada até a data selecionada; não são cotações oficiais.':'Preços simulados em USD × dólar de referência '+n(mkt().fx)+'. Cenário não altera custos históricos.'}</p></div>`}
function equityChart(r){
 const demo=chartDemo??(state.events.length>0&&state.events.every(e=>/^demo\d+$/.test(e.id)));
 let dates=[...new Set(r.rows.filter(e=>e.date.slice(0,10)>=start).map(e=>e.date.slice(0,10)))];
 if(r.rows.some(e=>e.date.slice(0,10)<start))dates.unshift(start);
 if(!dates.includes(end))dates.push(end);
 const samples=[['2026-01-01',1],['2026-02-01',1.025],['2026-03-01',.97],['2026-04-01',1.045],['2026-05-01',1.09],['2026-06-01',1.035],['2026-07-01',1.11],['2026-08-01',1.055],['2026-09-01',1.14],['2026-10-01',1.075]];
 if(demo)dates=[...new Set([...dates,...samples.map(x=>x[0]).filter(d=>d>=start&&d<=end)])];
 if(chartView==='columns'){
 dates=[];let cursor=new Date(start+'T12:00:00Z');cursor.setUTCDate(1);
 while(cursor.toISOString().slice(0,10)<=end&&dates.length<120){let next=new Date(cursor);next.setUTCMonth(next.getUTCMonth()+1);let close=new Date(next.getTime()-86400000).toISOString().slice(0,10);dates.push(close>end?end:close);cursor=next;}
 }
 dates.sort();
 let points=dates.map(d=>{let rr=E.replay(state.events,{owner,end:d}),mm=d===end&&end>='2026-10-31'?marks():rr.marks;let value=E.value(rr,mm).reduce((s,h)=>s+h.value,0),capital=rr.initial.reduce((s,x)=>s+x.value,0)+rr.flows.reduce((s,x)=>s+x.value,0);
 if(demo&&d!==end){let sample=samples.filter(x=>x[0]<=d).pop();if(sample)value=capital*sample[1];}
 return{date:d,value,capital};});
 const values=points.flatMap(p=>[p.value,p.capital]),actualLow=Math.min(...values),high=Math.max(...values,1),padding=Math.max((high-actualLow)*.18,high*.025,1);
 const min=Math.max(0,actualLow-padding),max=high+padding,span=max-min||1;
 const first=Date.parse(points[0]?.date||start),last=Date.parse(end),x=p=>40+(last===first?0:(Date.parse(p.date)-first)/(last-first))*570,y=v=>190-(v-min)/span*155;
 const xy=key=>points.map(p=>`${x(p)},${y(p[key])}`).join(' ');
 const area=points.length?`M${x(points[0])},190 L${points.map(p=>`${x(p)},${y(p.value)}`).join(' L')} L${x(points[points.length-1])},190 Z`:'';
 const controls=`<div class="chart-switch" role="group" aria-label="Visualização do gráfico">${['columns','lines'].map(v=>`<button class="textbtn" data-action="chartView" data-key="${v}" aria-pressed="${chartView===v}">${v==='columns'?'Colunas':'Linhas'}</button>`).join('')}</div>`;
 if(chartView==='columns'){
 const upper=Math.max(...points.map(p=>Math.max(p.capital,p.value)),1)*1.12,lower=Math.min(0,...points.map(p=>p.value-p.capital))*1.2,range=upper-lower,by=v=>205-(v-lower)/range*170,zero=by(0),step=560/Math.max(points.length,1),width=Math.min(34,step*.66);
 const short=v=>'R$ '+(Math.abs(v)>=1000?(v/1000).toLocaleString('pt-BR',{maximumFractionDigits:0})+' mil':n(v,0));
 const svg=`<svg class="equity-chart equity-bars" viewBox="0 0 660 255" role="img" aria-label="Evolução mensal: capital de referência, ganhos e perdas em reais">${[0,.25,.5,.75,1].map(t=>{let value=upper*(1-t),yy=by(value);return `<path d="M70 ${yy}H635" stroke="#e2e9ed"/><text x="62" y="${yy+3}" text-anchor="end" font-size="10" fill="#82939a">${short(value)}</text>`}).join('')}<path d="M70 ${zero}H635" stroke="#9cabb2"/>${points.map((p,i)=>{const xx=75+i*step+(step-width)/2,gain=p.value-p.capital;return `<g><title>${p.date}: capital ${brl(p.capital)}; ${gain<0?'perda':'ganho'} ${signed(gain)}; patrimônio ${brl(p.value)}${demo?' (simulado)':''}</title><rect x="${xx}" y="${Math.min(by(p.capital),zero)}" width="${width}" height="${Math.abs(by(p.capital)-zero)}" rx="3" fill="#27b47b"/>${gain>=0?`<rect x="${xx}" y="${by(p.value)}" width="${width}" height="${Math.abs(by(p.value)-by(p.capital))}" rx="3" fill="#96e7c2"/>`:`<rect x="${xx}" y="${zero}" width="${width}" height="${Math.abs(by(gain)-zero)}" rx="3" fill="#e88b8b"/>`}<text x="${xx+width/2}" y="235" text-anchor="middle" font-size="10" fill="#82939a">${p.date.slice(5,7)}/${p.date.slice(2,4)}</text></g>`}).join('')}${lower<0?`<text x="62" y="218" text-anchor="end" font-size="9" fill="#c16868">${short(lower)}</text>`:''}</svg>`;
 return `<div class="card"><div class="row wrap"><div><h2>Evolução do patrimônio</h2><span class="hint">${demo?'Histórico ilustrativo · dados fictícios':'Fechamento mensal pelos registros'}</span></div>${controls}</div><div class="row wrap chart-legend"><span><i style="background:#27b47b"></i>Capital de referência</span><span><i style="background:#96e7c2"></i>Ganho de capital</span><span><i style="background:#e88b8b"></i>Perda</span>${textbtn(demo?'Ver registros':'Modo apresentação','chartDemo')}</div>${svg}<p class="chart-caption">${demo?'Trajetória simulada para apresentação. ':''}Capital = saldos iniciais a custo + aportes − retiradas. Ganho/perda = patrimônio − capital; perdas aparecem abaixo de zero. Não representa apuração fiscal.${points.length===120?' Exibição limitada aos primeiros 120 meses do filtro.':''}</p></div>`;
 }
 return `<div class="card"><div class="row wrap"><div><h2>Evolução patrimonial ${demo?'simulada':'registrada'}</h2><span class="hint">${demo?'Trajetória ilustrativa para apresentação · dados fictícios':'Aportes separados do resultado'}</span></div><div class="badges">${controls}${textbtn(demo?'Ver registros':'Modo apresentação','chartDemo')}<span class="hint up">━ Patrimônio</span><span class="hint ambertext">┄ Capital de referência</span></div></div>${points.length?`<svg class="equity-chart" viewBox="0 0 660 220" role="img" aria-label="${demo?'Evolução fictícia para apresentação':'Patrimônio por data dos registros'}; eixo vertical ajustado"><defs><linearGradient id="equity-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#258469" stop-opacity=".22"/><stop offset="100%" stop-color="#258469" stop-opacity=".01"/></linearGradient></defs>${[0,.5,1].map(t=>`<path d="M40 ${35+t*155}H610" stroke="#edf0f2"/><text x="40" y="${28+t*155}" font-size="10" fill="#82939a">${esc(brl(max-t*span))}</text>`).join('')}<path d="${area}" fill="url(#equity-fill)"/><polyline points="${xy('capital')}" fill="none" stroke="#c49d58" stroke-width="2" stroke-dasharray="6 5"/><polyline points="${xy('value')}" fill="none" stroke="#258469" stroke-width="2.5" stroke-linejoin="round"/>${points.map(p=>`<circle cx="${x(p)}" cy="${y(p.value)}" r="3" fill="#258469" stroke="white" stroke-width="1"><title>${p.date}: patrimônio ${brl(p.value)}; capital ${brl(p.capital)}${demo?' (simulado)':''}</title></circle>`).join('')}</svg><div class="chart-bottom"><span>${esc(points[0].date.split('-').reverse().join('/'))}</span><span>${esc(end.split('-').reverse().join('/'))}</span></div>`:'<div class="empty">Adicione registros para ver a evolução.</div>'}<p class="chart-caption">${demo?'Histórico fictício com oscilações de mercado para demonstração. O ponto final corresponde ao patrimônio da carteira na data selecionada. Não altera operações, custos ou resultados.':'Reconstrução pelos preços de cada lançamento; sem histórico diário de mercado.'} Eixo vertical ajustado para destacar variações. Capital = saldos iniciais a custo + aportes − retiradas.</p></div>`;
}
function audit(r){let unknown=r.rows.filter(e=>e.country==='UNKNOWN').length,zero=r.rows.filter(e=>e.type==='OPENING'&&e.costBRL===0).length,unref=r.rows.filter(e=>['BUY','SELL','CONVERT'].includes(e.type)&&!e.reference).length;return{unknown,zero,unref}}
function overview(){let r=report(),s=E.period(r,start,end),a=audit(r);app.innerHTML=head('Resumo da carteira','Saldos, operações e resultados em reais.',button('＋ Registrar operação','add',true))+metrics(r)+`<div class="grid bottom">${equityChart(r)}<div class="card"><h2>Alertas da carteira</h2><div class="callout ${mkt().level==='red'?'warn':''}"><div class="row wrap">${pill('Contexto: '+mkt().name,mkt().level)}<span class="hint">Simulado</span></div><p>${esc(mkt().copy)}</p></div><div class="numbers-row" style="grid-template-columns:1fr 1fr"><div><span class="hint">Aportes no período</span><h3 style="margin-top:8px">${brl(s.deposits)}</h3></div><div><span class="hint">Retiradas no período</span><h3 style="margin-top:8px">${brl(s.withdrawals)}</h3></div></div><p class="audit-summary">${a.unknown+a.zero} dados a conferir ${info('Pendências de cadastro',a.unknown+' registros sem país da instituição e '+a.zero+' saldos iniciais com custo zero. Confira os documentos na Base fiscal. Isso não é uma validação fiscal completa.')}</p>${textbtn('Conferir base fiscal →','fiscal')}<div class="comparison"><b>Resultado após pagamentos de imposto</b><p class="${moneyClass(s.realized-s.tax)}">${signed(s.realized-s.tax)}</p><span class="hint">Lucro/prejuízo realizado menos os pagamentos de imposto cadastrados no período. Os pagamentos podem se referir a outro mês; este valor não é um resultado fiscal apurado.</span></div></div></div>`+holdingsTable(r)}
function operations(){const r=report(),rows=E.period(r,start,end).rows.filter(e=>(typeFilter==='all'||e.type===typeFilter)&&(!query||[e.asset,e.quote,e.venue,e.reference,e.owner].join(' ').toLowerCase().includes(query.toLowerCase()))).reverse();app.innerHTML=head('Operações','Compras, vendas, conversões e movimentações em um único livro.',button('＋ Registrar operação','add',true))+`<div class="card"><div class="row wrap"><div class="actionsbar"><label style="margin:0" for="searchOps"><span class="sr-only2">Buscar operações</span><input id="searchOps" placeholder="Ativo, corretora ou referência" value="${esc(query)}"></label><label style="margin:0" for="typeFilter"><span class="sr-only2">Filtrar tipo</span><select id="typeFilter">${[['all','Todos os tipos'],...Object.entries(types)].map(([k,v])=>`<option value="${k}" ${k===typeFilter?'selected':''}>${v}</option>`).join('')}</select></label></div><span class="hint">${rows.length} lançamentos encontrados</span></div><div class="tablewrap"><table><thead><tr><th>Data / titular</th><th>Tipo / ativo</th><th>Quantidade / preço</th><th>Corretora / moeda</th><th>Valor (R$) ${info('Valor (R$)','Valor bruto em reais para negociações; custo para saldo inicial; valor movimentado para aporte, retirada ou imposto. Transferência entre contas não é uma nova aplicação.')}</th><th>Taxas BRL</th><th>Resultado ${info('Resultado','Resultado das parcelas da operação, incluindo variação cambial e taxas. Abra Ver para conferir a composição.')}</th><th>Ações</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.date.replace('T',' '))}<br><small class="hint">${esc(e.owner)}</small></td><td><span class="op-type ${e.type==='SELL'?'sell':e.type==='BUY'?'buy':''}">${types[e.type]}</span><br><b style="display:inline-block;margin-top:7px">${esc(e.asset)}</b></td><td>${qty(e.qty)} ${esc(e.asset)}<br><small class="hint">${e.price?qty(e.price)+' '+esc(e.quote)+'/un.':'—'}</small></td><td>${esc(e.venue)}<br><small class="hint">${e.type==='TRANSFER'?'→ '+esc(e.toVenue):e.quote?esc(e.quote)+' · câmbio '+n(e.fx,4):''}</small></td><td>${brl(['BUY','SELL','CONVERT'].includes(e.type)?e.grossBRL:e.type==='OPENING'?e.costBRL:e.type==='TRANSFER'?0:e.qty*e.fx)}</td><td>${brl(e.feeBRL)}</td><td class="${moneyClass(e.resultBRL)}">${e.legs.length?signed(e.resultBRL):'—'}${e.tradeResult!==null?`<br><small class="hint">Venda: ${signed(e.tradeResult)}</small>`:''}</td><td><div class="inline-actions">${textbtn('Ver','viewOp',`data-id="${esc(e.id)}"`)}${textbtn('Editar','editOp',`data-id="${esc(e.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Nenhum lançamento no filtro.</td></tr>'}</tbody></table></div><p class="hint">Uma venda pode ter resultado do ativo e uma operação pode gerar variação de câmbio/conversão. O detalhe separa as parcelas. Ordem: data/hora em Brasília, sequência de cadastro e identificador.</p></div><div class="export-actions bottom">${button('Exportar operações CSV','exportOps')}${button('Backup completo JSON','backup')}${button('Restaurar backup JSON','import')}</div>`;$('typeFilter').onchange=e=>{typeFilter=e.target.value;operations()};$('searchOps').onchange=e=>{query=e.target.value;operations()}}
function fiscal(){const r=report(),s=E.period(r,start,end),a=audit(r),months=E.monthly(r,start,end);app.innerHTML=head('Resumo fiscal','Dados rastreáveis para apoiar a apuração e a declaração.',button('Exportar base mensal CSV','exportFiscal',true))+`<div class="fiscal-warning"><strong>Não calcula nem emite DARF.</strong>${info('Ajuda fiscal','Este resumo organiza os registros para conferência. Não calcula isenções, alíquotas, vencimentos ou imposto devido. Confira instituição, titular, tipo de operação e regras aplicáveis. Lucro gerencial não é necessariamente lucro tributável.')}</div><div class="numbers-row">${[['Total vendido',brl(s.volume),'Soma dos valores brutos das vendas no período, antes de taxas. Não representa lucro.'],['Resultado das vendas',signed(s.saleResult),'Valor líquido das vendas menos o custo das quantidades vendidas. Taxas já incluídas. Não representa imposto devido.'],['Câmbio e outros',signed(s.conversion),'Resultado de conversões, variação cambial e custos de rede. Pode ocorrer ao usar moedas de reserva.'],['Pagamentos de imposto',brl(s.tax),'Pagamentos cadastrados por você, pela data do pagamento. Não é um cálculo de imposto devido.']].map(([l,v,h])=>`<div class="number-small"><span>${l} ${info(l,h)}</span><strong>${v}</strong></div>`).join('')}</div><div class="card"><h2>Resumo por mês</h2><div class="tablewrap"><table class="fiscal-table"><thead><tr><th>Mês</th><th>Negociações</th><th>Vendas: lucro / perda / zero ${info('Vendas: lucro / perda / zero','Quantidade de vendas com lucro, com prejuízo e sem resultado, nessa ordem.')}</th><th>Vendas brutas</th><th>Resultado vendas</th><th>Câmbio e outros ${info('Câmbio e outros','Resultado ao usar ou converter moedas e ativos, somado aos custos de rede. Pode existir mesmo sem venda do ativo principal.')}</th><th>Taxas ${info('Taxas','Taxas em reais já consideradas no custo ou resultado. Não subtraia novamente.')}</th><th>Resultado total ${info('Resultado total','Soma dos resultados de vendas, conversões, câmbio e custos de rede. Taxas já consideradas; impostos não descontados.')}</th><th>Imposto registrado ${info('Imposto registrado','Pagamentos cadastrados manualmente, no mês em que foram pagos. A competência pode ser diferente. Não indica imposto devido.')}</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m.month}</td><td>${m.count}</td><td>${m.wins} / ${m.losses} / ${m.flat}</td><td>${brl(m.volume)}</td><td class="${moneyClass(m.saleResult)}">${signed(m.saleResult)}</td><td>${signed(m.conversion)}</td><td>${brl(m.fees)}</td><td class="${moneyClass(m.realized)}">${signed(m.realized)}</td><td>${brl(m.tax)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">Sem dados no período.</td></tr>'}</tbody></table></div><p class="hint">Taxas já integram custo ou resultado. A coluna de taxas é informativa e não deve ser abatida novamente. Impostos aparecem no mês do pagamento; competência fica preservada no lançamento e no CSV.</p></div><div class="grid bottom"><div class="card"><h2>Dados a conferir</h2><div class="insight"><span>◷</span><div><b>${a.unknown} registros sem localização da instituição</b>${info('País da instituição','Informe Brasil ou exterior conforme os documentos da instituição no cadastro da operação.')}</div></div><div class="insight"><span>◇</span><div><b>${a.unref} negociações sem referência externa</b>${info('Referência da operação','Use o identificador da ordem ou comprovante para comparar os lançamentos com seus documentos.')}</div></div><div class="insight"><span>▤</span><div><b>${a.zero} saldos iniciais com custo zero informado</b>${info('Custo zero','Confira a origem e o custo de aquisição. Custo desconhecido não deve ser informado como zero.')}</div></div><p class="hint">Não é uma validação completa da apuração fiscal.</p></div><div class="card"><h2>Exportar dados</h2><p>Operações, saldos e resumo mensal. ${info('O que os arquivos incluem','Os arquivos incluem titular, instituição, taxas, câmbio histórico, custos, resultados e referências de pagamentos. O backup JSON preserva também estratégias e revisões.')}</p><div class="export-actions">${button('Operações detalhadas CSV','exportOps')}${button('Saldos e custos CSV','exportHoldings')}${button('Backup JSON','backup')}</div></div></div>`}
function detail(){const r=report(),h=positions(r).find(x=>pk(x)===selected);if(!h){go('overview');toast('Não há posição aberta para este ativo no filtro.');return}const p=state.plans[selected],healthState=health(h),canPlan=Boolean(mkt().usd[h.asset])&&!FIAT.includes(h.asset)&&!['USDC','USDT'].includes(h.asset),usdPrice=mkt().usd[h.asset],ownerEquity=total(report(h.owner)),risk=p?Math.max(h.average-p.stop*mkt().fx,0)*h.qty/ownerEquity*100:0,giveback=p?Math.max(h.mark-p.stop*mkt().fx,0)*h.qty:0;app.innerHTML=textbtn('← Visão geral','overview')+head(h.asset+' · '+(catalog[h.asset]?.name||h.asset),esc(h.owner),button('＋ Registrar operação','addForAsset',true,`data-asset="${esc(h.asset)}" data-owner="${esc(h.owner)}"`))+`<div class="detail-layout"><aside class="card plan-panel" style="width:auto;display:block;background:white;color:var(--ink);padding:23px"><div class="row wrap"><h2>${canPlan?'Tese e estratégia':'Saldo e custo'}</h2>${canPlan?textbtn(p?'Editar':'Definir plano','plan',`data-key="${esc(selected)}"`):''}</div><div class="plan-line"><span>Quantidade em aberto</span><b>${qty(h.qty)} ${esc(h.asset)}</b></div><div class="plan-line"><span>Preço médio (R$)</span><b>${brl(h.average)}</b></div><p class="hint">Calculado pelas compras e custos históricos, separado por titular; consolidado entre corretoras.</p>${p?`<p>${esc(p.reason)}</p><div class="scenario-card bad"><span class="eyebrow negative">Cenário negativo</span><h3 style="margin-top:10px">Invalidação em US$ ${n(p.stop)}</h3><p>Risco máximo: ${percent(p.maxRisk)} ${info('Limite da estratégia','Percentual planejado sobre a carteira deste titular. Ao perder a referência, reavalie a posição. Nenhuma ordem é executada pelo app.')}</p></div><div class="scenario-card" style="margin-top:10px"><span class="eyebrow up">Cenário positivo</span><h3 style="margin-top:10px">Parcial em US$ ${n(p.target)}</h3><p>Parcial planejada: ${qty(p.partial)}% ${info('Parcial planejada','Percentual da quantidade a vender no objetivo, conforme sua estratégia. O app não executa a venda.')}</p></div><div class="comparison"><b>Risco / limite</b><p class="${risk>p.maxRisk?'negative':'up'}">${percent(risk)} / ${percent(p.maxRisk)}</p><span class="hint">(PM histórico BRL − invalidação convertida pelo dólar simulado atual) × quantidade / patrimônio do titular; piso zero.</span></div><div class="comparison"><b>Queda até a invalidação</b><p>${brl(giveback)} · ${percent(giveback/ownerEquity*100)}</p><span class="hint">Inclui devolução de lucro; taxas futuras e gaps não incluídos.</span></div>${button('Registrar revisão','review',true,`data-key="${esc(selected)}" style="width:100%"`)}`:`<p>${canPlan?'Defina invalidação e objetivo sem alterar o custo contábil das operações.':'Moeda de reserva também possui custo histórico em reais. Variação cambial pode gerar resultado quando utilizada ou convertida.'}</p>`}<div class="plan-line"><span>Custo do saldo</span><b>${brl(h.cost)}</b></div></aside><div class="detail-content"><div class="twostat"><div class="card"><span class="eyebrow">Situação da estratégia</span><div style="margin-top:12px">${pill(healthState.label,healthState.level)}</div></div><div class="card"><span class="eyebrow">Cenário de mercado</span><div style="margin-top:12px">${pill(canPlan?mkt().name:'Reserva / câmbio',canPlan?mkt().level:'neutral')}</div></div></div><div class="card bottom"><div class="row wrap"><div><span class="eyebrow">Valor da posição</span><div class="position-price">${brl(h.value)}</div><span class="hint">${brl(h.mark)} por unidade · ${end<'2026-10-31'?'última referência do livro':'preço simulado'}</span></div><div><span class="eyebrow">Resultado aberto</span><h2 class="${moneyClass(h.unrealized)}" style="font-size:25px;margin-top:10px">${signed(h.unrealized)}</h2><span class="hint">${h.cost?percent(h.unrealized/h.cost*100):'Custo zero informado'} sobre o custo em aberto</span></div></div>${p?`<div class="price-rail" style="margin-top:35px"><span class="marker" style="left:calc(${Math.max(0,Math.min(100,(usdPrice-p.stop)/(p.target-p.stop)*100))}% - 2px)"></span></div><div class="rail-labels"><span>Invalidação US$ ${qty(p.stop)}</span><span>Preço US$ ${qty(usdPrice)}</span><span>Objetivo US$ ${qty(p.target)}</span></div>`:''}</div>${canPlan?`<div class="card bottom"><h2>Contexto do mercado</h2><div class="context-strip" style="grid-template-columns:repeat(3,1fr)">${[['Juros EUA · 10 anos',mkt().rates],['Petróleo',mkt().oil],['S&P 500',mkt().sp]].map(([l,v])=>`<div><span class="eyebrow">${l}</span><strong>${v}</strong></div>`).join('')}</div><p class="sub">${esc(mkt().copy)}</p>${info('Como o alerta funciona','O cenário usa valores fictícios, sem previsão de preços. Estresse combina alta de juros e petróleo com queda de ações. Preservar suporte não garante alta; pressão macro não garante queda. Registrar uma revisão não remove o alerta.')}</div>`:''}<div class="card bottom"><h2>Operações que formam esta posição</h2><div class="timeline2" style="margin-top:20px">${r.rows.filter(e=>e.owner===h.owner&&(e.asset===h.asset||e.quote===h.asset||e.feeCurrency===h.asset)).reverse().map(e=>`<div><div class="row wrap"><b>${types[e.type]} · ${esc(e.date.replace('T',' '))}</b>${textbtn('Detalhes','viewOp',`data-id="${esc(e.id)}"`)}</div><p>${qty(e.qty)} ${esc(e.asset)} ${e.price?'a '+qty(e.price)+' '+esc(e.quote):''} · ${esc(e.venue)}</p></div>`).join('')}</div></div><div class="card bottom"><h2>Revisões da estratégia</h2>${state.reviews.filter(x=>x.key===selected).slice().reverse().map(x=>`<div class="operation-line"><b>${esc(x.decision)}</b><p>${esc(x.text)}</p><span class="hint">${esc(x.date)} · ${esc(x.context)} · referência ${brl(x.price)}</span></div>`).join('')||'<p class="hint">Nenhuma revisão registrada.</p>'}</div></div></div>`}
function settings(){app.innerHTML=head('Dados e backup','Titulares separados e backup do livro completo.')+`<div class="grid"><div class="card"><div class="row"><h2>Titulares</h2>${textbtn('＋ Adicionar','addOwner')}</div>${state.owners.map(o=>`<div class="plan-line"><b>${esc(o)}</b><span class="hint">Custo médio independente</span></div>`).join('')}<p class="hint">A visão família soma valores, mas não mistura o custo dos titulares.</p></div><div class="card"><h2>Backup e recuperação</h2><p>Dados salvos neste navegador. Exporte um backup.</p><div class="export-actions">${button('Exportar backup JSON','backup',true)}${button('Restaurar JSON','import')}</div><p class="hint">Restauração substitui a v3 após validação e confirmação. Não é importação de corretora.</p></div></div><div class="fiscal-warning"><strong>Protótipo com exemplos fictícios.</strong>Para começar seu próprio livro, use a opção abaixo. O custo de saldos anteriores precisa ser conhecido e informado; saldo inicial não é lucro nem aporte novo.</div><div class="export-actions">${button('Começar livro vazio','empty')}${button('Restaurar exemplos fictícios','reset')}</div>`}
function render(){const nav=[['overview','◫','Visão geral'],['operations','≡','Operações'],['fiscal','▤','Base fiscal'],['settings','⚙','Dados e backup']];$('nav').innerHTML=nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${i} &nbsp; ${t}</button>`).join('');$('crumb').textContent=page==='detail'?'Detalhe da posição':nav.find(x=>x[0]===page)[2];$('scenario').value=state.scenario;$('filters').innerHTML=`<label for="ownerFilter">Titular<select id="ownerFilter"><option value="all">Todos os titulares</option>${state.owners.map(o=>`<option ${owner===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label><label for="dateStart">De<input id="dateStart" type="date" value="${start}" required></label><label for="dateEnd">Até<input id="dateEnd" type="date" value="${end}" required></label><span class="filter-note">Operações e resultados usam o intervalo De–Até. A carteira mostra o saldo acumulado até a data Até, incluindo operações anteriores ao período.</span>`;for(let id of ['ownerFilter','dateStart','dateEnd'])$(id).onchange=()=>{let s=$('dateStart').value,e=$('dateEnd').value;if(!s||!e||s>e){toast('Informe um intervalo de datas válido.');render();return}start=s;end=e;owner=$('ownerFilter').value;render()};({overview,operations,fiscal,settings,detail}[page])()}
function show(title,fields,handler){$('modalTitle').textContent=title;$('fields').innerHTML=fields;$('formError').textContent='';form.oninput=null;form.onchange=null;form.onsubmit=e=>{e.preventDefault();try{handler(new FormData(form))}catch(err){$('formError').textContent=err.message}};modal.showModal()}
const fieldHelp={
 country:['País da instituição','Informe Brasil ou exterior conforme os documentos da corretora ou instituição. Essa informação ajuda a organizar a conferência fiscal.'],
 costBRL:['Custo total (R$)','Custo de aquisição do saldo anterior, incluindo taxas. Não é seu valor de mercado hoje. Use zero apenas se o custo for comprovadamente zero.'],
 fx:['Cotação em reais','Valor em reais de 1 unidade da moeda usada na operação, na data em que ela ocorreu. Exemplo: 1 USDC = R$ 5,20 → informe 5,20. Para BRL, o valor é 1.'],
 feeFx:['Cotação da taxa (R$)','Valor em reais de 1 unidade da moeda da taxa na data da operação. Preenchido automaticamente quando a taxa é na moeda ou ativo negociado; para outro token, informe a cotação histórica.'],
 feeQty:['Valor da taxa','Quantidade paga na moeda da taxa. Exemplo: taxa de 2 USDC → informe 2 e selecione USDC.'],
 taxPeriod:['Mês de referência','Mês das operações a que o imposto se refere. Pode ser diferente da data em que você pagou. Os totais da tela usam a data do pagamento.'],
 taxSource:['De onde saiu o pagamento','Fora da carteira apenas registra o pagamento. Debitar do saldo reduz a moeda na conta selecionada. O imposto precisa ter sido apurado e pago por você.'],
 planStop:['Preço de invalidação (US$)','Preço em que a estratégia deixa de fazer sentido e precisa ser revista. Serve como referência; o app não envia uma ordem de stop.'],
 planRisk:['Risco máximo (%)','Percentual máximo planejado do patrimônio do titular nesta posição. A estimativa considera preço médio, invalidação, câmbio simulado e quantidade. Não inclui taxas futuras ou gaps.'],
 planPartial:['Parcial planejada (%)','Percentual da quantidade da posição que você pretende vender ao atingir o objetivo. Nenhuma venda é automática.'],
 reference:['Ordem ou comprovante','Identificador da ordem, transferência ou pagamento para facilitar a conferência com a corretora e seus documentos.']
};
function fieldLabel(id,label){const help=fieldHelp[id];return help?esc(help[0]):label}
const input=(id,label,value,type='text',extra='')=>`<div><label for="${id}">${fieldLabel(id,label)}</label>${fieldHelp[id]?info(fieldHelp[id][0],fieldHelp[id][1]):''}<input id="${id}" name="${id}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;
const select=(id,label,options,value)=>`<div><label for="${id}">${fieldLabel(id,label)}</label>${fieldHelp[id]?info(fieldHelp[id][0],fieldHelp[id][1]):''}<select id="${id}" name="${id}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
let editing=null,opDefault={};
function opFields(d){const t=d.type,trade=['BUY','SELL','CONVERT'].includes(t),moving=['DEPOSIT','WITHDRAW','TAX'].includes(t),initial=t==='OPENING',transfer=t==='TRANSFER';return `<div class="form-grid three">${select('type','Tipo de lançamento',Object.entries(types),t)}${select('opOwner','Titular',state.owners.map(o=>[o,o]),d.owner)}${input('date','Data / hora · Brasília',d.date,'datetime-local','required')}</div><div class="form-grid three">${input('venue','Corretora / conta / carteira',d.venue,'text','required maxlength="80"')}${select('country','Localização da instituição',[['UNKNOWN','Não informado'],['BR','Brasil'],['EX','Exterior']],d.country)}${select('asset',trade?(t==='CONVERT'?'Ativo recebido':'Ativo negociado'):'Ativo / moeda',(moving?FIAT:ASSETS).map(a=>[a,a]),moving&&!FIAT.includes(d.asset)?'BRL':d.asset)}</div><div class="form-grid three">${input('qty',trade&&t==='CONVERT'?'Quantidade recebida':'Quantidade',d.qty,'number','required min="0.00000001" max="1000000000000" step="any"')}${trade?input('price',t==='CONVERT'?'Unidades pagas por ativo recebido':'Preço unitário na moeda abaixo',d.price,'number','required min="0.00000001" max="1000000000000" step="any"')+select('quote',t==='CONVERT'?'Moeda / ativo entregue':'Moeda de negociação',ASSETS.map(a=>[a,a]),d.quote):initial?input('costBRL','Custo histórico total em BRL',d.costBRL,'number','required min="0" max="1000000000000000000" step="any"'):transfer?input('toVenue','Carteira / conta de destino',d.toVenue||'','text','required maxlength="80"'):''}${!initial&&!transfer?input('fx',trade?'1 unidade da moeda de negociação em BRL':'1 unidade da moeda em BRL',d.fx,'number','required min="0.00000001" max="1000000000" step="any"'):''}</div>${transfer?'<p class="hint">Transferência entre contas do mesmo titular: move custódia sem venda. Se a origem ou destino for de outra pessoa, não use este tipo.</p>':''}${trade||transfer?`<details ${d.feeQty?'open':''}><summary>Taxas da operação</summary><div class="form-grid three">${input('feeQty','Quantidade da taxa',d.feeQty||0,'number','required min="0" max="1000000000000" step="any"')}${select('feeCurrency','Moeda da taxa',ASSETS.map(a=>[a,a]),d.feeCurrency||d.quote)}${input('feeFx','1 unidade da moeda da taxa em BRL',d.feeFx||1,'number','required min="0.00000001" step="any"')}</div><p class="hint">Se a taxa estiver no ativo ou na moeda negociada, a cotação é vinculada ao preço da operação. Para BNB ou outro token, informe o valor histórico e tenha saldo registrado.</p></details>`:''}${t==='TAX'?`<div class="form-grid">${input('taxPeriod','Competência do imposto',d.taxPeriod||'','month')}${select('taxSource','Origem do pagamento',[['external','Fora da carteira (só registro)'],['portfolio','Debitar do saldo desta conta']],d.taxSource||'external')}</div><p class="hint">Informe o imposto já apurado/pago. O sistema não calcula a obrigação.</p>`:''}<div class="form-grid">${input('reference','ID da ordem / comprovante',d.reference||'','text','maxlength="100"')}${input('notes','Observação / origem do custo',d.notes||'','text','maxlength="500"')}</div><div id="opPreview" class="record-help"></div>${initial?'<p class="hint">Custo zero só deve ser usado quando efetivamente conhecido como zero. Inclua a origem/documentação no campo observação. Saldos iniciais ficam separados dos aportes novos.</p>':''}${trade?'<p class="hint">Em compras/vendas, quantidade × preço forma o valor bruto. Conversões são registradas uma única vez, com perna de saída e de entrada derivadas automaticamente.</p>':''}`}
function eventFromForm(f,source){const d={...source,id:editing?.id||'op'+Date.now(),sequence:editing?.sequence||Math.max(0,...state.events.map(e=>e.sequence||0))+1,type:String(f.get('type')),owner:String(f.get('opOwner')),date:String(f.get('date')),venue:String(f.get('venue')||'').trim(),country:String(f.get('country')),asset:String(f.get('asset')),qty:Number(f.get('qty')),price:Number(f.get('price')||0),quote:String(f.get('quote')||'BRL'),fx:Number(f.get('fx')||1),feeQty:Number(f.get('feeQty')||0),feeCurrency:String(f.get('feeCurrency')||'BRL'),feeFx:Number(f.get('feeFx')||1),reference:String(f.get('reference')||'').trim(),notes:String(f.get('notes')||'').trim(),costBRL:Number(f.get('costBRL')||0),toVenue:String(f.get('toVenue')||'').trim(),taxPeriod:String(f.get('taxPeriod')||''),taxSource:String(f.get('taxSource')||'external')};if(['BUY','SELL','CONVERT'].includes(d.type)){if(d.quote==='BRL')d.fx=1;if(d.feeCurrency===d.quote)d.feeFx=d.fx;else if(d.feeCurrency===d.asset)d.feeFx=d.price*d.fx;else if(d.feeCurrency==='BRL')d.feeFx=1;}else if(d.feeCurrency==='BRL')d.feeFx=1;if(['DEPOSIT','WITHDRAW','TAX'].includes(d.type)&&d.asset==='BRL')d.fx=1;return d}
function addOperation(id=null,defaults={}){editing=id?state.events.find(e=>e.id===id):null;let d=editing?cl(editing):{type:'BUY',owner:owner==='all'?state.owners[0]:owner,date:'2026-10-31T09:00',venue:'Binance',country:'UNKNOWN',asset:'BTC',qty:.001,price:79200,quote:'USDC',fx:5.2,feeQty:0,feeCurrency:'USDC',feeFx:5.2,...defaults};opDefault=d;
 show(editing?'Editar lançamento':'Registrar operação',opFields(d),f=>{const e=eventFromForm(f,d);E.validate(e);if(e.reference&&state.events.some(x=>x.id!==e.id&&x.owner===e.owner&&x.venue===e.venue&&x.reference===e.reference))throw Error('Referência já cadastrada para este titular e conta. Confira possível duplicidade.');const candidate=state.events.filter(x=>x.id!==e.id).concat(e);E.replay(candidate);state.events=candidate;persist();modal.close();render();toast('Livro recalculado. Preço médio, resultado e saldos atualizados.');});wireOp(d)
}
function wireOp(d){const update=()=>{try{const e=eventFromForm(new FormData(form),d),trade=['BUY','SELL','CONVERT'].includes(e.type),fee=e.feeQty*e.feeFx;let gross=trade?e.qty*e.price*e.fx:e.type==='OPENING'?e.costBRL:e.qty*e.fx;let candidate=state.events.filter(x=>x.id!==e.id).concat(e);let r=E.replay(candidate),row=r.rows.find(x=>x.id===e.id);$('opPreview').innerHTML=`<div class="row wrap"><span>Valor da operação: <b>${brl(gross)}</b></span><span>Taxas: <b>${brl(fee)}</b></span></div>${row.legs.length?`<p>Lucro/prejuízo: <b class="${moneyClass(row.resultBRL)}">${signed(row.resultBRL)}</b> · ${row.tradeResult!==null?'venda '+signed(row.tradeResult)+' · ':''}câmbio e outros resultados ${signed(row.conversionResult+row.feeResult)}</p>`:''}<span class="hint">${e.type==='TRANSFER'?'Movimenta custódia, preserva o preço médio; a taxa reduz o resultado.':e.type==='OPENING'?'Estabelece custo e quantidade anteriores, sem gerar lucro.':'Prévia válida para todo o histórico, inclusive operações posteriores.'}</span>`;if($('fx')){let auto=trade?e.quote==='BRL':e.asset==='BRL';$('fx').readOnly=auto;if(auto)$('fx').value='1'}if($('feeFx')){let auto=e.feeCurrency==='BRL'||(trade&&[e.asset,e.quote].includes(e.feeCurrency));$('feeFx').readOnly=auto;if(auto)$('feeFx').value=String(e.feeFx)}}catch(err){$('opPreview').innerHTML=`<span class="ambertext">${esc(err.message)}</span>`}};
 $('type').onchange=()=>{let current=eventFromForm(new FormData(form),d);current.type=$('type').value;if(['DEPOSIT','WITHDRAW','TAX'].includes(current.type)){current.asset='BRL';current.qty=100;current.fx=1;current.feeQty=0}else if(current.type==='OPENING'){current.costBRL=0;current.feeQty=0}else if(['BUY','SELL','CONVERT'].includes(current.type)&&current.asset==='BRL'){current.asset='BTC';current.quote='USDC';current.qty=.001;current.price=79200;current.fx=5.2}if(current.type==='TRANSFER')current.toVenue='Carteira própria';$('fields').innerHTML=opFields(current);wireOp(current)};for(let id of ['asset','quote','feeCurrency'])if($(id))$(id).addEventListener('change',()=>{if(id==='quote'&&$('fx')){$('fx').value=$('quote').value==='BRL'?'1':String(marks()[$('quote').value]||1)}if(id==='asset'&&['DEPOSIT','WITHDRAW','TAX'].includes($('type').value)&&$('fx'))$('fx').value=$('asset').value==='BRL'?'1':String(mkt().fx);update()});form.oninput=update;form.onchange=update;update()}
function viewOperation(id){const r=E.replay(state.events),e=r.rows.find(x=>x.id===id);if(!e)return;show(types[e.type]+' · '+e.asset,`<div class="operation-line"><b>${esc(e.owner)} · ${esc(e.date.replace('T',' '))}</b><p>${esc(e.venue)} · instituição: ${e.country==='UNKNOWN'?'não informada':e.country==='BR'?'Brasil':'Exterior'} · sequência ${e.sequence}</p><p>Referência: ${esc(e.reference||'não informada')}</p></div><div class="result-split"><div>Quantidade<b>${qty(e.qty)} ${esc(e.asset)}</b></div><div>Custo da operação<b>${brl(e.costBasisBRL)}</b></div><div>Taxas das operações<b>${brl(e.feeBRL)}</b></div><div>Resultado total<b class="${moneyClass(e.resultBRL)}">${signed(e.resultBRL)}</b></div></div>${e.legs.map(l=>`<div class="operation-line"><b>${esc(l.asset)} · ${esc(({sale:'Venda do ativo',funding:'Moeda utilizada na compra',conversion:'Ativo entregue na conversão',fee:'Pagamento de taxa','withdraw-fx':'Câmbio na retirada','tax-fx':'Câmbio no pagamento','network-expense':'Despesa de rede' })[l.category]||l.category)}</b><p>Quantidade ${qty(l.qty)} · valor ${brl(l.valueBRL)} · custo baixado ${brl(l.costBRL)} · resultado ${signed(l.resultBRL)}</p></div>`).join('')}<p class="hint">${e.type==='OPENING'?'Custo unitário histórico informado: '+brl(e.costBRL/e.qty)+'. Referência cadastral:':'Cotação histórica: '+n(e.fx,6)+' BRL por unidade de'} ${esc(['BUY','SELL','CONVERT'].includes(e.type)?e.quote:e.asset)}. Taxas não devem ser subtraídas novamente dos resultados exibidos.</p>${e.type==='TAX'?`<p>Competência: ${esc(e.taxPeriod||'não informada')} · origem: ${e.taxSource==='portfolio'?'saldo da conta':'fora da carteira'}</p>`:''}<p>${esc(e.notes)}</p><div class="actionsbar">${textbtn('Editar lançamento','editFromDetail',`data-id="${esc(e.id)}"`)}${textbtn('Excluir lançamento','deleteOp',`data-id="${esc(e.id)}"`)}</div>`,()=>modal.close())}
function removeOp(id){const e=state.events.find(x=>x.id===id);if(!e)return;show('Excluir lançamento?',`<p>${types[e.type]} de ${qty(e.qty)} ${esc(e.asset)}, em ${esc(e.date)}.</p><p>Todo o livro será reprocessado. A exclusão será recusada se deixar alguma operação posterior sem saldo. Exporte um backup antes se quiser preservar esta versão.</p>`,()=>{const events=state.events.filter(x=>x.id!==id);E.replay(events);state.events=events;persist();modal.close();render();toast('Lançamento excluído e histórico recalculado.');})}
function editPlan(key){const h=positions(report()).find(x=>pk(x)===key);if(!h)return;const ref=mkt().usd[h.asset],p=state.plans[key]||{stop:ref*.92,target:ref*1.15,partial:25,maxRisk:2,reason:'Acompanhar a posição com limites definidos.'};show('Estratégia · '+h.asset,`<p>Defina os limites da posição. ${info('Estratégia','Esses níveis orientam os alertas. Não alteram o preço médio nem executam ordens.')}</p><div class="form-grid">${input('planStop','Invalidação em USD',p.stop,'number','required min="0.00000001" step="any"')}${input('planTarget','Objetivo em USD',p.target,'number','required min="0.00000001" step="any"')}${input('planRisk','Limite de risco da carteira (%)',p.maxRisk,'number','required min=".01" max="100" step=".01"')}${input('planPartial','Parcial planejada (%)',p.partial,'number','required min=".01" max="100" step=".01"')}</div>${input('planReason','Motivo em uma frase',p.reason,'text','required maxlength="300"')}`,f=>{const plan={stop:Number(f.get('planStop')),target:Number(f.get('planTarget')),maxRisk:Number(f.get('planRisk')),partial:Number(f.get('planPartial')),reason:String(f.get('planReason')).trim()};if(!plan.reason||!Number.isFinite(plan.stop)||!Number.isFinite(plan.target)||plan.stop<=0||plan.target<=plan.stop)throw Error('Informe motivo e objetivo maior que a invalidação.');state.plans[key]=plan;persist();modal.close();render();toast('Estratégia atualizada; custo médio preservado.');})}
function review(key){const h=positions().find(x=>pk(x)===key);if(!h)return;show('Revisar '+h.asset,`${pill(health(h).label,health(h).level)} ${pill(mkt().name,mkt().level)}${select('decision','Decisão',[['Manter e acompanhar','Manter e acompanhar'],['Revisar proteção','Revisar proteção'],['Planejar redução','Planejar redução'],['Aguardar confirmação','Aguardar confirmação']], 'Manter e acompanhar')}${input('reviewText','Motivo (opcional)','','text','maxlength="500"')}<p>Revisão não executa ordens. ${info('Registro da revisão','A revisão registra sua decisão sem alterar saldo, custo ou alertas. Se já vendeu, registre a venda em Operações.')}</p>`,f=>{state.reviews.push({key,date:new Date().toLocaleString('pt-BR',{timeZone:'America/Fortaleza'}),decision:String(f.get('decision')),text:String(f.get('reviewText')),price:h.mark,context:mkt().name,plan:cl(state.plans[key]||{})});persist();modal.close();render();toast('Revisão registrada. Operações e alertas preservados.');})}
function download(name,data,mime){const url=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportOps(){let rows=E.period(report(),start,end).rows.map(e=>({id:e.id,sequencia:e.sequence,data_brasilia:e.date,titular:e.owner,instituicao:e.venue,localizacao:e.country,tipo:types[e.type],ativo:e.asset,quantidade:e.qty,preco_unitario:e.price,moeda_negociacao:e.quote,cotacao_BRL:['OPENING','TRANSFER'].includes(e.type)?'':e.fx,bruto_BRL:e.grossBRL,liquido_BRL:e.netBRL,custo_baixado_ou_incorporado_BRL:e.costBasisBRL,saldo_inicial_custo_BRL:e.type==='OPENING'?e.costBRL:'',valor_movimentacao_BRL:['DEPOSIT','WITHDRAW','TAX'].includes(e.type)?e.qty*e.fx:'',taxa_quantidade:e.feeQty,taxa_moeda:e.feeCurrency,taxa_cotacao_BRL:e.feeFx,taxa_valor_BRL:e.feeBRL,resultado_venda_BRL:e.tradeResult??'',resultado_conversao_cambio_BRL:e.conversionResult,resultado_taxas_rede_BRL:e.feeResult,resultado_total_BRL:e.resultBRL,quantidade_final_ativo:e.inventoryAfter,PM_final_BRL:e.avgAfter,transferencia_destino:e.toVenue||'',competencia_imposto:e.taxPeriod||'',origem_pagamento:e.taxSource||'',referencia:e.reference,observacao:e.notes,pernas_json:JSON.stringify(e.legs)}));download('lastro-operacoes-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function exportHoldings(){let rows=positions().map(h=>({data_final:end,titular:h.owner,ativo:h.asset,quantidade:h.qty,PM_BRL:h.average,custo_aberto_BRL:h.cost,preco_referencia_BRL:h.mark,valor_marcado_BRL:h.value,resultado_aberto_BRL:h.unrealized,fonte:end<'2026-10-31'?'Ultimo preco registrado':'Simulacao Lastro',custodia_json:JSON.stringify(Object.entries(report(h.owner).custody).filter(([k,v])=>k.endsWith('|'+h.asset)&&v>E.EPS))}));download('lastro-carteira-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function exportFiscal(){let rows=[];for(let o of owner==='all'?state.owners:[owner]){let r=report(o);for(let m of E.monthly(r,start,end))rows.push({titular:o,mes:m.month,negociacoes:m.count,vendas:m.sales,vendas_com_lucro:m.wins,vendas_com_prejuizo:m.losses,vendas_neutras:m.flat,vendas_brutas_BRL:m.volume,resultado_vendas_BRL:m.saleResult,conversoes_cambio_rede_BRL:m.conversion,resultado_realizado_BRL:m.realized,taxas_BRL:m.fees,impostos_pagos_BRL:m.tax,aportes_BRL:m.deposits,retiradas_BRL:m.withdrawals})}download('lastro-base-mensal-'+end+'.csv',E.csv(rows),'text/csv;charset=utf-8')}
function backup(){download('lastro-backup-v3-'+end+'.json',JSON.stringify(state,null,2),'application/json')}
function reset(empty=false){show(empty?'Começar um livro vazio?':'Restaurar exemplos fictícios?',`<p>Esta ação substitui os dados da v3 neste navegador. Exporte um backup para preservar operações, estratégias e revisões. As versões anteriores permanecem separadas.</p>${empty?input('newOwner','Primeiro titular','','text','required maxlength="80"'):''}`,f=>{if(empty){let name=String(f.get('newOwner')).trim();if(!name||name.includes('|'))throw Error('Informe um nome sem o caractere |.');state={version:3,owners:[name],scenario:'mixed',events:[],plans:{},reviews:[]}}else state=cl(seed);owner='all';persist();modal.close();go('overview');toast(empty?'Livro vazio pronto. Comece por aportes ou saldos iniciais.':'Exemplos restaurados.');})}
function addOwner(){show('Adicionar titular',input('name','Nome do titular','','text','required maxlength="80"'),f=>{let name=String(f.get('name')).trim();if(!name||name.includes('|')||state.owners.some(x=>x.toLowerCase()===name.toLowerCase()))throw Error('Nome inválido ou já cadastrado. Não use |.');state.owners.push(name);persist();modal.close();render()})}
$('backupFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5e6)throw Error('Backup acima de 5 MB.');let candidate=check(JSON.parse(await file.text()));show('Restaurar backup v3?',`<p>${candidate.events.length} lançamentos e ${candidate.owners.length} titulares. O histórico passou na validação de saldos. Salvar substituirá o livro local; exporte seu backup atual antes de confirmar.</p>`,()=>{state=candidate;owner='all';persist();modal.close();go('overview');toast('Backup restaurado e livro recalculado.');})}catch(err){toast('Backup não importado: '+err.message)}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-holding],[data-action]');if(!el)return;if(el.dataset.page)return go(el.dataset.page);if(el.dataset.holding)return openHolding(el.dataset.holding);let a=el.dataset.action,id=el.dataset.id,key=el.dataset.key;switch(a){case'chartView':chartView=key;overview();break;case'chartDemo':chartDemo=!(chartDemo??(state.events.length>0&&state.events.every(e=>/^demo\d+$/.test(e.id))));overview();break;case'overview':case'fiscal':go(a);break;case'add':addOperation();break;case'addForAsset':addOperation(null,{asset:el.dataset.asset,owner:el.dataset.owner});break;case'viewOp':viewOperation(id);break;case'editOp':addOperation(id);break;case'editFromDetail':modal.close();addOperation(id);break;case'deleteOp':modal.close();removeOp(id);break;case'plan':editPlan(key);break;case'review':review(key);break;case'exportOps':exportOps();break;case'exportHoldings':exportHoldings();break;case'exportFiscal':exportFiscal();break;case'backup':backup();break;case'import':$('backupFile').click();break;case'reset':reset();break;case'empty':reset(true);break;case'addOwner':addOwner();break}});
document.addEventListener('keydown',e=>{let row=e.target.closest('[data-holding]');if(row&&['Enter',' '].includes(e.key)){e.preventDefault();openHolding(row.dataset.holding)}});
$('scenario').onchange=e=>{state.scenario=e.target.value;persist();render();toast('Mercado simulado alterado. Custos históricos permanecem iguais.');};$('reset').onclick=()=>reset();$('closeModal').onclick=()=>modal.close();$('cancelModal').onclick=()=>modal.close();
installHelp();render();if(recovery)toast('Dados v3 inválidos ou indisponíveis. Exibindo exemplos; backup inválido não foi sobrescrito.');
